-- AGT-7: one row for every model call attempt, with what went in and what came out. Rows are only ever added.
-- id is generated by the database and gives the order in which the attempts were recorded.
-- reduction_steps holds one "index:KIND:version" entry per prompt reduction step, joined by ";" (empty for none).
-- input_fingerprint is a SHA-256 hash written as 64 hexadecimal characters.
-- recorded_at is filled by the database; the application does not set or read it.
CREATE TABLE model_call (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    run_id UUID NOT NULL REFERENCES runs (id),
    role VARCHAR(255) NOT NULL,
    role_version VARCHAR(255) NOT NULL,
    profile VARCHAR(255) NOT NULL,
    model VARCHAR(255) NOT NULL,
    attempt_kind VARCHAR(255) NOT NULL,
    input_fingerprint VARCHAR(64) NOT NULL,
    system_text TEXT NOT NULL,
    user_text TEXT NOT NULL,
    answer_text TEXT,
    finish_reason VARCHAR(255),
    estimated_prompt_tokens BIGINT NOT NULL,
    estimated_answer_tokens BIGINT,
    reported_prompt_tokens BIGINT,
    reported_answer_tokens BIGINT,
    reduction_steps TEXT NOT NULL,
    duration_ms BIGINT NOT NULL,
    outcome VARCHAR(255) NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- A run's attempts are read in the order they were recorded.
CREATE INDEX idx_model_call_run_id_id ON model_call (run_id, id);
